counterexample:
INSERT INTO t1 (c1, c2) VALUES ('b', 't1b');
INSERT INTO t2 (c1, c2) VALUES ('c', 't2c');
INSERT INTO t3 (c1, c2) VALUES ('a', 't3a');
INSERT INTO t3 (c1, c2) VALUES ('d', 't3d');
